# 🗾 日本行每日：每天一個單元（照片教學＋句子＋對話＋今日 5 句必背），附在 7 個行前單元後面。
# 新增一天：在 DAYS 尾端加一個 dict（id 用 d+月日，例如 d1026），照片放 img/<id>/（長邊 ≤1280px、WebP q75、每張 ≤200KB），
# 然後 python3 tools/build.py && python3 tools/gen.py audio（只會產生新句子的音檔）。
# 句子 tuple：(ja, kana, zh, note, L)；L＝《文化初級日本語》課別（課外的寫「課外…／簡單說法：…」）。
# 對話台詞：('me'|'f'|'f2'|'m2', ja)＝引用本單元句子；或 (role, ja, kana, zh, note, L)。
# words：照片裡的日文 (ja, kana, zh, [例句×3])；例句 (ja, kana, zh, L)，限第 1～12 課文法（課外要標「課外…／簡單說法：…」）。單字和例句都有音檔（1x＋0.7x）。
# refs：展會會話（行前 7 單元）裡可以直接套用的句子 (ja, 說明)。
